import * as pulumi from "@pulumi/pulumi";
import * as aws from "@pulumi/aws";

export interface AppInfrastructureArgs {
    environment: "dev" | "prod";
    vpcId: pulumi.Input<string>;
    subnetIds: pulumi.Input<string[]>;
    securityGroupId: pulumi.Input<string>;
    bucketName: pulumi.Input<string>;
    dbUsername: pulumi.Input<string>;
    dbPassword: pulumi.SecretInput;
    // Optional: EKS OIDC provider ARN for prod trust policy
    oidcProviderArn?: pulumi.Input<string>;
}

export class AppInfrastructure extends pulumi.ComponentResource {
    public readonly bucketArn: pulumi.Output<string>;
    public readonly rdsEndpoint: pulumi.Output<string>;
    public readonly iamRoleArn: pulumi.Output<string>;
    public readonly dbSecret: pulumi.Output<string>;

    constructor(name: string, args: AppInfrastructureArgs, opts?: pulumi.ComponentResourceOptions) {
        super("custom:infra:AppStack", name, {}, opts);

        const isProd = args.environment === "prod";

        // -----------------------------------------------------------------------
        // 1. S3 Bucket: Versioning, Encryption, No Public Access
        // -----------------------------------------------------------------------
        const bucket = new aws.s3.BucketV2(`${name}-assets`, {
            bucket: args.bucketName,
            versioning: { enabled: true },
            tags: { Environment: args.environment, ManagedBy: "pulumi" }
        }, { parent: this });

        new aws.s3.BucketPublicAccessBlock(`${name}-bucket-block`, {
            bucket: bucket.id,
            blockPublicAcls: true,
            blockPublicPolicy: true,
            ignorePublicAcls: true,
            restrictPublicBuckets: true,
        }, { parent: this });

        new aws.s3.BucketServerSideEncryptionConfiguration(`${name}-bucket-encrypt`, {
            bucket: bucket.id,
            rule: {
                applyServerSideEncryptionConfiguration: {
                    sseAlgorithm: isProd ? "aws:kms" : "AES256",
                    kmsMasterKeyId: isProd ? "alias/aws/s3" : undefined,
                }
            }
        }, { parent: this });

        this.bucketArn = bucket.arn;

        // -----------------------------------------------------------------------
        // 2. RDS PostgreSQL: Deletion Protection, Backup, Network Isolation
        // -----------------------------------------------------------------------
        const dbSubnetGroup = new aws.rds.SubnetGroup(`${name}-db-subnet`, {
            name: `${name}-db-subnet`,
            subnetIds: args.subnetIds,
            tags: { Environment: args.environment }
        }, { parent: this });

        const dbInstance = new aws.rds.Instance(`${name}-db`, {
            engine: "postgres",
            engineVersion: "15.4",
            instanceClass: isProd ? "db.t3.medium" : "db.t3.micro",
            allocatedStorage: 20,
            dbName: "appdb",
            username: args.dbUsername,
            password: args.dbPassword,
            publiclyAccessible: false,                // Criterion 2
            skipFinalSnapshot: true,
            storageEncrypted: isProd,
            multiAz: isProd,
            deletionProtection: true,                 // Criterion 2
            backupRetentionPeriod: 7,                 // Criterion 2
            vpcSecurityGroupIds: [args.securityGroupId],
            dbSubnetGroupName: dbSubnetGroup.name,
            tags: { Environment: args.environment }
        }, { parent: this });

        this.rdsEndpoint = dbInstance.endpoint;

        // -----------------------------------------------------------------------
        // 3. IAM Role: Least Privilege, No Wildcards on Prod
        // -----------------------------------------------------------------------
        const trustPolicy = isProd
            ? {
                Version: "2012-10-17",
                Statement: [{
                    Effect: "Allow",
                    Principal: { Federated: args.oidcProviderArn! },
                    Action: "sts:AssumeRoleWithWebIdentity",
                    Condition: {
                        StringEquals: { "token-issuer": args.oidcProviderArn!.apply(arn => arn.split("/").pop()) }
                    }
                }]
            }
            : {
                Version: "2012-10-17",
                Statement: [{ Effect: "Allow", Principal: { AWS: "*" }, Action: "sts:AssumeRole" }]
            };

        const role = new aws.iam.Role(`${name}-app-role`, {
            name: `${name}-app-role`,
            assumeRolePolicy: pulumi.jsonStringify(trustPolicy),
            tags: { Environment: args.environment }
        }, { parent: this });

